it('streams a header and one row per grade', async () => {
  await seedClass('c_t', { students: 3, quizzes: 2 });
  const res = await request(app).get('/classes/c_t/grades.csv').set(teacherAuth('c_t'));
  expect(res.headers['content-type']).toMatch(/text\/csv/);
  expect(res.text.trim().split('\n')).toHaveLength(7);
});
it('rejects teachers of other classes', async () => {
  const res = await request(app).get('/classes/c_t/grades.csv').set(teacherAuth('c_other'));
  expect(res.status).toBe(403);
});
